function getSolarCycleItemDescription(itemName) {
  var base = getSolarCycleBackpackItemBaseName(itemName).toLowerCase();
  if (!base) return null;
  var catalogs = [NEW_SUN_STAGE_RELIC_REWARDS, NEW_SUN_ENDING_RELIC_REWARDS];
  for (var c = 0; c < catalogs.length; c++) {
    var cat = catalogs[c] || {};
    var keys = Object.keys(cat);
    for (var i = 0; i < keys.length; i++) {
      var reward = cat[keys[i]];
      if (!reward || !reward.name) continue;
      if (String(reward.name).toLowerCase() === base) {
        return {
          name: reward.name,
          kind: reward.kind || 'relic',
          stat: reward.stat || '',
          summary: reward.summary || 'A New Sun relic with campaign-level consequences.',
          source: (c === 0) ? 'stage' : 'ending'
        };
      }
    }
  }
  return null;
}

function ensureSolarCycleRelicRewardState(sc) {
  var state = sc || ensureSolarCycleState();
  if (!state) return null;
  if (!state.relicRewardsGiven || typeof state.relicRewardsGiven !== 'object') state.relicRewardsGiven = {};
  return state.relicRewardsGiven;
}

function getSolarCycleBackpackItemBaseName(raw) {
  if (!raw) return '';
  var text = String(raw || '');
  if (typeof parseBackpackStack === 'function') {
    var parsed = parseBackpackStack(text);
    if (parsed && parsed.name) text = String(parsed.name);
  }
  text = text.split('(')[0].trim();
  if (typeof normalizeLegacyLootAlias === 'function') text = normalizeLegacyLootAlias(text);
  return String(text || '').trim();
}

function hasSolarCycleRelicName(name) {
  var target = String(name || '').toLowerCase();
  if (!target) return false;
  if (typeof hasOwnedItemName === 'function' && hasOwnedItemName(name)) return true;

  var items = [];
  if (Array.isArray(S && S.backpack)) items = items.concat(S.backpack.filter(Boolean));
  if (S && S.equipment) {
    ['weapon1', 'weapon2', 'armor', 'readied'].forEach(function (slot) {
      if (S.equipment[slot]) items.push(S.equipment[slot]);
    });
  }
  return items.some(function (entry) {
    return getSolarCycleBackpackItemBaseName(entry).toLowerCase() === target;
  });
}

function tryStoreSolarCycleRelicReward(reward) {
  if (!reward || !reward.name) return false;
  var display = reward.name;
  if (reward.stat && (reward.kind === 'weapon' || reward.kind === 'armor')) {
    display = reward.name + ' (' + reward.stat + ')';
  }

  if (reward.kind === 'weapon' && S && S.equipment) {
    if (!S.equipment.weapon1) {
      S.equipment.weapon1 = display;
      if (typeof setInputValue === 'function') setInputValue('eqWeapon1', display);
      return true;
    }
    if (!S.equipment.weapon2) {
      S.equipment.weapon2 = display;
      if (typeof setInputValue === 'function') setInputValue('eqWeapon2', display);
      return true;
    }
  }

  if (reward.kind === 'armor' && S && S.equipment && !S.equipment.armor) {
    S.equipment.armor = display;
    if (typeof setInputValue === 'function') setInputValue('eqArmor', display);
    return true;
  }

  if (typeof addToBackpack === 'function') return !!addToBackpack(display);
  if (typeof addItemToBackpack === 'function') return !!addItemToBackpack(display);
  return false;
}

function awardSolarCycleRelicReward(reward, sourceTag) {
  var sc = ensureSolarCycleState();
  if (!sc || !reward || !reward.id) return null;
  var seen = ensureSolarCycleRelicRewardState(sc);
  if (!seen) return null;
  if (seen[reward.id]) return null;
  if (hasSolarCycleRelicName(reward.name)) {
    seen[reward.id] = true;
    return { granted: false, duplicate: true, name: reward.name, summary: reward.summary || '' };
  }

  var stored = tryStoreSolarCycleRelicReward(reward);
  if (!stored) {
    var credits = Math.max(40, Number(reward.fallbackCredits || 100));
    if (typeof changeCredits === 'function') changeCredits(credits);
    else S.credits = Math.max(0, Number(S.credits || 0) + credits);
    if (typeof showNotif === 'function') {
      showNotif('Backpack full: ' + reward.name + ' converted to +' + credits + '₵.', 'warn');
    }
    return { granted: false, converted: true, credits: credits, name: reward.name, summary: reward.summary || '' };
  }

  seen[reward.id] = true;
  if (typeof updateAllStatDisplays === 'function') updateAllStatDisplays();
  if (typeof renderBackpackUI === 'function') renderBackpackUI();
  if (typeof renderWeaponModsPanel === 'function') renderWeaponModsPanel();
  if (typeof showNotif === 'function') {
    showNotif('New Sun relic acquired (' + String(sourceTag || 'arc') + '): ' + reward.name + '.', 'good');
  }
  return { granted: true, name: reward.name, summary: reward.summary || '' };
}

function awardSolarCycleStageRelicReward(stageId) {
  var reward = NEW_SUN_STAGE_RELIC_REWARDS[String(stageId || '')];
  if (!reward) return null;
  return awardSolarCycleRelicReward(reward, 'stage');
}

function awardSolarCycleEndingRelicReward(endingKey) {
  var reward = NEW_SUN_ENDING_RELIC_REWARDS[String(endingKey || '')];
  if (!reward) return null;
  return awardSolarCycleRelicReward(reward, 'ending');
}

function consumeSolarCycleBackpackItem(index, itemName) {
  if (typeof consumeBackpackItemByName === 'function') {
    if (consumeBackpackItemByName(itemName)) return true;
  }
  if (typeof removeBackpackItem === 'function') {
    removeBackpackItem(index);
    return true;
  }
  if (Array.isArray(S && S.backpack) && index >= 0 && index < S.backpack.length) {
    S.backpack[index] = '';
    return true;
  }
  return false;
}

function clearOneSolarCycleNegativeCondition() {
  if (!S || !S.conditions) return '';
  var keys = ['weakened', 'distracted', 'shaken', 'vulnerable'];
  for (var i = 0; i < keys.length; i += 1) {
    if (S.conditions[keys[i]]) {
      S.conditions[keys[i]] = false;
      return keys[i];
    }
  }
  return '';
}

function handleSolarCycleRelicBackpackUse(index) {
  if (!Array.isArray(S && S.backpack)) return false;
  var entry = S.backpack[index];
  if (!entry) return false;
  var name = getSolarCycleBackpackItemBaseName(entry).toLowerCase();
  if (!name) return false;

  if (name === 'claw of the conciliator') {
    consumeSolarCycleBackpackItem(index, 'Claw of the Conciliator');
    var heal = typeof explodingRoll === 'function' ? explodingRoll(8).total : roll(8);
    if (typeof changeHealth === 'function') changeHealth(-heal);
    else if (typeof changeStress === 'function') changeStress(-heal);
    if (typeof changeMentalStress === 'function') changeMentalStress(-1);
    var cleared = clearOneSolarCycleNegativeCondition();
    if (S.trauma > 0 && typeof updateTrauma === 'function') {
      S.trauma = Math.max(0, Number(S.trauma || 0) - 1);
      updateTrauma();
    }
    if (typeof updateConditionButtons === 'function') updateConditionButtons();
    if (typeof updateAllStatDisplays === 'function') updateAllStatDisplays();
    if (typeof renderBackpackUI === 'function') renderBackpackUI();
    if (typeof openModal === 'function') {
      openModal('Claw of the Conciliator', '<div style="font-size:.9rem;color:var(--text2);line-height:1.65;">'
        + 'The relic warms in your hand and knits flesh with impossible mercy.<br><br>'
        + '<strong style="color:var(--green2);">Recovered ' + heal + ' Health</strong> and <strong style="color:var(--teal);">-1 Mental Stress</strong>'
        + (cleared ? ('<br>Condition cleared: <strong>' + String(cleared) + '</strong>.') : '')
        + '</div>');
    }
    return true;
  }

  if (name === 'book of the new sun') {
    consumeSolarCycleBackpackItem(index, 'Book of the New Sun');
    if (typeof ensureRelicBonusState === 'function') ensureRelicBonusState();
    S.relicValorBonuses = S.relicValorBonuses || {};
    S.relicValorBonuses.mind = Math.max(0, Number(S.relicValorBonuses.mind || 0)) + 1;
    S.relicValorBonuses.spirit = Math.max(0, Number(S.relicValorBonuses.spirit || 0)) + 1;
    if (typeof changeCounter === 'function') changeCounter('tmw', 1);
    else S.tmw = Math.max(0, Number(S.tmw || 0) + 1);
    if (typeof updateAllStatDisplays === 'function') updateAllStatDisplays();
    if (typeof renderBackpackUI === 'function') renderBackpackUI();
    if (typeof showNotif === 'function') showNotif('Book of the New Sun attuned: permanent +V.D. to Mind and Spirit.', 'good');
    return true;
  }

  if (name === "autarch's signet") {
    consumeSolarCycleBackpackItem(index, "Autarch's Signet");
    S.conditions = S.conditions || {};
    S.conditions.focused = true;
    S.conditions.protected = true;
    S.rollMod = S.rollMod || { advDice: [], flat: 0, addValor: 0 };
    S.rollMod.addValor = Math.max(0, Number(S.rollMod.addValor || 0) + 1);
    if (typeof updateConditionButtons === 'function') updateConditionButtons();
    if (typeof updateRollModDisplay === 'function') updateRollModDisplay();
    if (typeof updateAllStatDisplays === 'function') updateAllStatDisplays();
    if (typeof renderBackpackUI === 'function') renderBackpackUI();
    if (typeof showNotif === 'function') showNotif("Autarch's Signet invoked: Focused + Protected and +V.D. queued (additive).", 'good');
    return true;
  }

  if (name === 'new sun puzzle sigil') {
    consumeSolarCycleBackpackItem(index, 'New Sun Puzzle Sigil');
    if (typeof changeCounter === 'function') changeCounter('tmw', 1);
    else S.tmw = Math.max(0, Number(S.tmw || 0) + 1);
    S.rollMod = S.rollMod || { advDice: [], flat: 0, addValor: 0 };
    S.rollMod.addValor = Math.max(0, Number(S.rollMod.addValor || 0) + 1);
    if (typeof updateRollModDisplay === 'function') updateRollModDisplay();
    if (typeof updateAllStatDisplays === 'function') updateAllStatDisplays();
    if (typeof renderBackpackUI === 'function') renderBackpackUI();
    if (typeof showNotif === 'function') showNotif('New Sun Puzzle Sigil aligned: +1 TMW and +V.D. queued (additive).', 'good');
    return true;
  }

  if (name === 'fractured new sun puzzle sigil') {
    consumeSolarCycleBackpackItem(index, 'Fractured New Sun Puzzle Sigil');
    var sc = ensureSolarCycleState();
    var gainedCharge = false;
    if (sc && sc.timeFracture) {
      var current = Number(sc.timeFracture.charges || 0);
      var cap = Math.max(1, Number(sc.timeFracture.maxCharges || 1));
      if (current < cap) {
        sc.timeFracture.charges = Math.min(cap, current + 1);
        gainedCharge = true;
      }
      if (sc.timeFracture.scarFlags && typeof sc.timeFracture.scarFlags === 'object') {
        sc.timeFracture.scarFlags.paradoxStrain = Math.max(0, Number(sc.timeFracture.scarFlags.paradoxStrain || 0) + 1);
      }
      if (typeof updateSolarCycleTimeFractureUI === 'function') updateSolarCycleTimeFractureUI();
    }
    if (!gainedCharge) {
      S.rollMod = S.rollMod || { advDice: [], flat: 0, addValor: 0 };
      S.rollMod.addValor = Math.max(0, Number(S.rollMod.addValor || 0) + 1);
      if (typeof updateRollModDisplay === 'function') updateRollModDisplay();
    }
    if (typeof updateAllStatDisplays === 'function') updateAllStatDisplays();
    if (typeof renderBackpackUI === 'function') renderBackpackUI();
    if (typeof showNotif === 'function') {
      showNotif(gainedCharge
        ? 'Fractured Sigil stabilized: +1 Time Fracture charge (Paradox Strain +1).'
        : 'Fractured Sigil resonated: +V.D. queued (additive, Paradox Strain +1).', 'warn');
    }
    return true;
  }

  return false;
}

function patchSolarCycleRelicBackpackUse(retryCount) {
  var tries = Number(retryCount || 0);
  if (window._solarCycleRelicUsePatched) return true;
  if (typeof window.useBackpackItem !== 'function') {
    if (tries < 20) {
      setTimeout(function () { patchSolarCycleRelicBackpackUse(tries + 1); }, 250);
    }
    return false;
  }
  window._solarCycleRelicUsePatched = true;
  var base = window.useBackpackItem;
  window.useBackpackItem = function (index) {
    if (handleSolarCycleRelicBackpackUse(index)) return;
    return base.apply(this, arguments);
  };
  return true;
}

function getSolarCycleDayKey() {
  const gd = (S && S.gameDate) ? S.gameDate : {};
  return [gd.year || 1, gd.month || 1, gd.day || 1].join('-');
}

function clampSolarCycleElapsed(value) {
  const n = Number(value || 0);
  if (!Number.isFinite(n)) return 0;
  return Math.max(0, Math.min(SOLAR_CYCLE_DAY_LIMIT, Math.floor(n)));
}

function getSolarCycleTier(daysElapsed) {
  const day = clampSolarCycleElapsed(daysElapsed);
  if (day >= 90) return 'terminal';
  if (day >= 70) return 'late';
  if (day >= 35) return 'mid';
  return 'early';
}

function ensureSolarCycleState() {
  if (typeof S === 'undefined') return null;
  S.solarCycle = S.solarCycle || {};
  const sc = S.solarCycle;

  if (typeof sc.storyModeEnabled !== 'boolean') sc.storyModeEnabled = false;
  if (typeof sc.enabled !== 'boolean') sc.enabled = false;
  if (!sc.storyModeEnabled && sc.enabled) sc.enabled = false;
  if (typeof sc.startDayKey !== 'string') sc.startDayKey = '';
  sc.daysElapsed = clampSolarCycleElapsed(sc.daysElapsed);
  sc.daysRemaining = Math.max(0, SOLAR_CYCLE_DAY_LIMIT - sc.daysElapsed);
  if (typeof sc.worldTilt !== 'number') sc.worldTilt = sc.daysElapsed > 0 ? Math.min(4, Math.floor(sc.daysElapsed / 25) + 1) : 0;
  if (!Array.isArray(sc.prophecyTrack)) sc.prophecyTrack = [];
  if (!sc.finalePressure || typeof sc.finalePressure !== 'object') {
    sc.finalePressure = { shownDays: {}, pending: null, lastDay: 0, lastEnding: '', lastWeight: 0 };
  }
  if (!sc.finalePressure.shownDays || typeof sc.finalePressure.shownDays !== 'object') sc.finalePressure.shownDays = {};
  if (typeof sc.finalePressure.lastDay !== 'number') sc.finalePressure.lastDay = 0;
  if (typeof sc.finalePressure.lastEnding !== 'string') sc.finalePressure.lastEnding = '';
  if (typeof sc.finalePressure.lastWeight !== 'number') sc.finalePressure.lastWeight = 0;
  if (!sc.finalePressure.influence || typeof sc.finalePressure.influence !== 'object') sc.finalePressure.influence = {};
  NEW_SUN_ENDING_KEYS.forEach(function (key) {
    if (typeof sc.finalePressure.influence[key] !== 'number') sc.finalePressure.influence[key] = 0;
  });
  if (!sc.relicRewardsGiven || typeof sc.relicRewardsGiven !== 'object') sc.relicRewardsGiven = {};
  if (typeof sc.echoSeed !== 'number') sc.echoSeed = Math.floor(Math.random() * 1000000);
  if (SOLAR_CYCLE_ARCS.indexOf(sc.activeArc) < 0) sc.activeArc = 'relic';
  if (!sc.resolvedMarkers || typeof sc.resolvedMarkers !== 'object') sc.resolvedMarkers = {};
  if (!sc.endingFlags || typeof sc.endingFlags !== 'object') sc.endingFlags = { forcedFinaleTriggered: false, ending: '' };
  if (typeof sc.endingFlags.forcedFinaleTriggered !== 'boolean') sc.endingFlags.forcedFinaleTriggered = false;
  if (typeof sc.endingFlags.ending !== 'string') sc.endingFlags.ending = '';
  if (!sc.timeFracture || typeof sc.timeFracture !== 'object') {
    sc.timeFracture = { charges: 1, maxCharges: 1, scarFlags: {}, rewindsUsed: 0 };
  }
  if (typeof sc.timeFracture.charges !== 'number') sc.timeFracture.charges = 1;
  if (typeof sc.timeFracture.maxCharges !== 'number') sc.timeFracture.maxCharges = 1;
  if (!sc.timeFracture.scarFlags || typeof sc.timeFracture.scarFlags !== 'object') sc.timeFracture.scarFlags = {};
  if (typeof sc.timeFracture.rewindsUsed !== 'number') sc.timeFracture.rewindsUsed = 0;
  if (typeof sc.timeFracture.scarFlags.paradoxStrain !== 'number') sc.timeFracture.scarFlags.paradoxStrain = 0;
  if (typeof sc.timeFracture.scarFlags.echoArc !== 'string') sc.timeFracture.scarFlags.echoArc = '';
  if (typeof sc.timeFracture.scarFlags.lastRewindDays !== 'number') sc.timeFracture.scarFlags.lastRewindDays = 0;
  if (typeof sc.timeFracture.scarFlags.tmwBurnTotal !== 'number') sc.timeFracture.scarFlags.tmwBurnTotal = 0;
  if (!sc.arcProgress || typeof sc.arcProgress !== 'object') sc.arcProgress = {};
  if (typeof sc.arcProgress.stageIndex !== 'number') sc.arcProgress.stageIndex = 0;
  if (!sc.arcProgress.postedStageIds || typeof sc.arcProgress.postedStageIds !== 'object') sc.arcProgress.postedStageIds = {};
  if (!sc.arcProgress.completedStageIds || typeof sc.arcProgress.completedStageIds !== 'object') sc.arcProgress.completedStageIds = {};
  if (!sc.arcProgress.branchChoices || typeof sc.arcProgress.branchChoices !== 'object') sc.arcProgress.branchChoices = {};
  if (!sc.arcProgress.stageResults || typeof sc.arcProgress.stageResults !== 'object') sc.arcProgress.stageResults = {};
  if (!sc.arcProgress.activeMarker || typeof sc.arcProgress.activeMarker !== 'object') sc.arcProgress.activeMarker = null;
  // New Sun Arc Campaign is locked to canonical straight routing.
  sc.arcProgress.routeMode = 'straight';
  if (typeof sc.arcProgress.lastAutoOpenedMarkerKey !== 'string') sc.arcProgress.lastAutoOpenedMarkerKey = '';
  if (!Array.isArray(sc.arcProgress.history)) sc.arcProgress.history = [];
  if (typeof sc.arcProgress.lastSyncedCompletedCount !== 'number') sc.arcProgress.lastSyncedCompletedCount = 0;
  if (!sc.playstyle || typeof sc.playstyle !== 'object') sc.playstyle = { observe: 0, intervene: 0, ignore: 0 };
  if (typeof sc.playstyle.observe !== 'number') sc.playstyle.observe = 0;
  if (typeof sc.playstyle.intervene !== 'number') sc.playstyle.intervene = 0;
  if (typeof sc.playstyle.ignore !== 'number') sc.playstyle.ignore = 0;
  if (!sc.finale || typeof sc.finale !== 'object') sc.finale = { resolved: false, key: '', text: '' };
  if (typeof sc.finale.resolved !== 'boolean') sc.finale.resolved = false;
  if (typeof sc.finale.key !== 'string') sc.finale.key = '';
  if (typeof sc.finale.text !== 'string') sc.finale.text = '';
  if (!Array.isArray(sc.thresholdNotifs)) sc.thresholdNotifs = [];
  if (typeof sc.sideStoryLastSpawnDay !== 'number') sc.sideStoryLastSpawnDay = -1;
  if (typeof sc.sideStoryPressureMemory !== 'number') sc.sideStoryPressureMemory = 0;
  if (typeof sc.currentOmen !== 'string') sc.currentOmen = '';
  if (!sc.pendingEchoMarker || typeof sc.pendingEchoMarker !== 'object') sc.pendingEchoMarker = null;
  if (!sc.questScheduler || typeof sc.questScheduler !== 'object') sc.questScheduler = {};
  if (!sc.questScheduler.completedByRegion || typeof sc.questScheduler.completedByRegion !== 'object') {
    sc.questScheduler.completedByRegion = { province: 0, sea: 0, wtw: 0, galaxy: 0, planet: 0 };
  }
  if (typeof sc.questScheduler.completedByRegion.planet !== 'number') sc.questScheduler.completedByRegion.planet = 0;
  if (!Array.isArray(sc.questScheduler.activeQuestIds)) sc.questScheduler.activeQuestIds = [];
  if (!sc.questScheduler.questById || typeof sc.questScheduler.questById !== 'object') sc.questScheduler.questById = {};
  if (!Array.isArray(sc.questScheduler.clueLedger)) sc.questScheduler.clueLedger = [];
  if (!sc.questScheduler.methodSignals || typeof sc.questScheduler.methodSignals !== 'object') sc.questScheduler.methodSignals = {};
  if (typeof sc.questScheduler.routeTemplate !== 'string') sc.questScheduler.routeTemplate = 'roaming';
  if (typeof sc.questScheduler.questCounter !== 'number') sc.questScheduler.questCounter = 0;
  if (!sc.questScheduler.wtwQuestByHex || typeof sc.questScheduler.wtwQuestByHex !== 'object') sc.questScheduler.wtwQuestByHex = {};
  if (!sc.questScheduler.questActionStats || typeof sc.questScheduler.questActionStats !== 'object') sc.questScheduler.questActionStats = {};
  if (!sc.questScheduler.approachStats || typeof sc.questScheduler.approachStats !== 'object') sc.questScheduler.approachStats = { investigate: 0, fracture: 0, misled: 0, portal: 0 };
  if (!sc.questScheduler.actionProfile || typeof sc.questScheduler.actionProfile !== 'object') sc.questScheduler.actionProfile = { byStat: {}, byChallenge: {} };
  if (!sc.questScheduler.actionProfile.byStat || typeof sc.questScheduler.actionProfile.byStat !== 'object') sc.questScheduler.actionProfile.byStat = {};
  if (!sc.questScheduler.actionProfile.byChallenge || typeof sc.questScheduler.actionProfile.byChallenge !== 'object') sc.questScheduler.actionProfile.byChallenge = {};
  if (!sc.questScheduler.npcVectors || typeof sc.questScheduler.npcVectors !== 'object') sc.questScheduler.npcVectors = {};
  if (!sc.questScheduler.regionPostedCount || typeof sc.questScheduler.regionPostedCount !== 'object') sc.questScheduler.regionPostedCount = { province: 0, sea: 0, wtw: 0, galaxy: 0, planet: 0 };
  if (typeof sc.questScheduler.regionPostedCount.planet !== 'number') sc.questScheduler.regionPostedCount.planet = 0;
  if (typeof sc.questScheduler.lastSpawnDay !== 'number') sc.questScheduler.lastSpawnDay = -1;
  if (typeof sc.questScheduler.lastFailureBranchDay !== 'number') sc.questScheduler.lastFailureBranchDay = -1;
  sc.currentTier = getSolarCycleTier(sc.daysElapsed);
  if (!sc.currentOmen) {
    sc.currentOmen = (SOLAR_CYCLE_OMENS[sc.activeArc] && SOLAR_CYCLE_OMENS[sc.activeArc][sc.currentTier])
      ? SOLAR_CYCLE_OMENS[sc.activeArc][sc.currentTier]
      : '';
  }
  return sc;
}

const CONSEQUENCE_TENSION_KEYS = ['stability', 'scarcity', 'corruption', 'rumor', 'witness', 'factionHeat'];

function clampConsequenceTension(value) {
  return Math.max(-10, Math.min(10, Number(value || 0)));
}

function ensureConsequenceFabricState() {
  if (typeof S === 'undefined') return null;
  S.consequenceFabric = S.consequenceFabric || {
    tensions: {
      stability: 0,
      scarcity: 0,
      corruption: 0,
      rumor: 0,
      witness: 0,
      factionHeat: 0
    },
    timeline: [],
    lastBySystem: {}
  };
  var cf = S.consequenceFabric;
  if (!cf.tensions || typeof cf.tensions !== 'object') cf.tensions = {};
  CONSEQUENCE_TENSION_KEYS.forEach(function (k) {
    cf.tensions[k] = clampConsequenceTension(cf.tensions[k]);
  });
  if (!Array.isArray(cf.timeline)) cf.timeline = [];
  if (!cf.lastBySystem || typeof cf.lastBySystem !== 'object') cf.lastBySystem = {};
  return cf;
}

function getConsequenceTimelineDayLabel() {
  var cycleDay = (S && S.solarCycle && typeof S.solarCycle.daysElapsed === 'number')
    ? Number(S.solarCycle.daysElapsed || 0)
    : 0;
  if (cycleDay > 0) return 'New Sun Day ' + cycleDay;
  var gd = S && S.gameDate ? S.gameDate : null;
  if (!gd) return 'Day 0';
  return 'Y' + Number(gd.year || 1) + ' M' + Number(gd.month || 1) + ' D' + Number(gd.day || 1);
}

function recordWorldConsequence(entry) {
  var cf = ensureConsequenceFabricState();
  if (!cf) return null;
  var ev = entry || {};
  var deltas = ev.deltas && typeof ev.deltas === 'object' ? ev.deltas : {};

  CONSEQUENCE_TENSION_KEYS.forEach(function (k) {
    var delta = Number(deltas[k] || 0);
    if (!delta) return;
    cf.tensions[k] = clampConsequenceTension(Number(cf.tensions[k] || 0) + delta);
  });

  var item = {
    id: 'cf-' + Date.now() + '-' + Math.floor(Math.random() * 10000),
    title: String(ev.title || 'World state shifted'),
    detail: String(ev.detail || ''),
    system: String(ev.system || 'world'),
    region: String(ev.region || ''),
    severity: String(ev.severity || 'info'),
    dayLabel: getConsequenceTimelineDayLabel(),
    ts: Date.now(),
    deltas: {}
  };

  CONSEQUENCE_TENSION_KEYS.forEach(function (k) {
    var delta = Number(deltas[k] || 0);
    if (delta) item.deltas[k] = delta;
  });

  cf.timeline.push(item);
  if (cf.timeline.length > 120) cf.timeline = cf.timeline.slice(-120);
  cf.lastBySystem[item.system] = item.title;
  return item;
}

function getConsequenceMissionBias() {
  var cf = ensureConsequenceFabricState();
  var t = cf ? (cf.tensions || {}) : {};
  var corruption = Number(t.corruption || 0);
  var scarcity = Number(t.scarcity || 0);
  var stability = Number(t.stability || 0);
  var rumor = Number(t.rumor || 0);
  var witness = Number(t.witness || 0);
  var factionHeat = Number(t.factionHeat || 0);

  var focusRegion = '';
  if (corruption >= 4) focusRegion = 'wtw';
  else if (scarcity >= 4) focusRegion = 'sea';
  else if (rumor >= 4) focusRegion = 'province';
  else if (witness >= 4) focusRegion = 'galaxy';

  var difficultyShift = 0;
  if (corruption + factionHeat >= 8) difficultyShift = 1;
  else if (stability >= 5 && witness >= 3) difficultyShift = -1;

  var rewardBonus = Math.max(-30, Math.min(80, (Math.max(0, corruption) * 8) + (Math.max(0, scarcity) * 6) - (Math.max(0, stability) * 4)));

  var preferredVerbs = ['Investigate', 'Recover'];
  if (scarcity >= 3) preferredVerbs = ['Deliver', 'Escort', 'Recover'];
  if (corruption >= 3) preferredVerbs = ['Sabotage', 'Investigate', 'Eliminate'];
  if (witness >= 3) preferredVerbs = ['Rescue', 'Guard', 'Escort'];

  return {
    focusRegion: focusRegion,
    difficultyShift: difficultyShift,
    rewardBonus: rewardBonus,
    preferredVerbs: preferredVerbs,
    tensionSummary: {
      stability: stability,
      scarcity: scarcity,
      corruption: corruption,
      rumor: rumor,
      witness: witness,
      factionHeat: factionHeat
    }
  };
}

function buildConsequenceMotionPanelHtml(limit) {
  var cf = ensureConsequenceFabricState();
  var maxRows = Math.max(3, Number(limit || 6));
  var t = cf ? (cf.tensions || {}) : {};
  var tone = function (v) {
    var n = Number(v || 0);
    if (n >= 5) return 'var(--red2)';
    if (n >= 2) return 'var(--gold2)';
    if (n <= -5) return 'var(--green2)';
    if (n <= -2) return 'var(--teal)';
    return 'var(--muted2)';
  };
  var timeline = cf && Array.isArray(cf.timeline) ? cf.timeline : [];
  var timelineHtml = timeline.length
    ? timeline.slice(-maxRows).reverse().map(function (row) {
      return '<div style="border-bottom:1px solid var(--border2);padding:.22rem 0;">'
        + '<div style="font-size:.73rem;color:var(--text2);line-height:1.45;">' + escapeSolarCycleHtml(row.title || 'State shift') + '</div>'
        + '<div style="font-size:.68rem;color:var(--muted2);line-height:1.45;">' + escapeSolarCycleHtml(row.dayLabel || '')
          + (row.region ? (' · ' + escapeSolarCycleHtml(String(row.region).toUpperCase())) : '')
          + (row.detail ? (' · ' + escapeSolarCycleHtml(row.detail)) : '')
          + '</div>'
        + '</div>';
    }).join('')
    : '<div style="font-size:.73rem;color:var(--muted2);">No consequences recorded yet. Resolve quests, missions, and faction actions to shape the world.</div>';

  return '<div style="background:var(--surface2);border:1px solid var(--border2);padding:.65rem .75rem;margin-bottom:.6rem;">'
    + '<div style="font-size:.82rem;color:var(--gold2);margin-bottom:.22rem;"><strong>Consequences in Motion</strong></div>'
    + '<div style="font-size:.74rem;color:var(--muted2);line-height:1.5;margin-bottom:.3rem;">The world reacts across systems. These tensions alter mission pressure, faction responses, and available routes.</div>'
    + '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:.22rem;margin-bottom:.32rem;">'
    + '<div style="font-size:.7rem;color:' + tone(t.stability) + ';">Stability: <strong>' + Number(t.stability || 0) + '</strong></div>'
    + '<div style="font-size:.7rem;color:' + tone(t.scarcity) + ';">Scarcity: <strong>' + Number(t.scarcity || 0) + '</strong></div>'
    + '<div style="font-size:.7rem;color:' + tone(t.corruption) + ';">Corruption: <strong>' + Number(t.corruption || 0) + '</strong></div>'
    + '<div style="font-size:.7rem;color:' + tone(t.rumor) + ';">Rumor: <strong>' + Number(t.rumor || 0) + '</strong></div>'
    + '<div style="font-size:.7rem;color:' + tone(t.witness) + ';">Witness Trust: <strong>' + Number(t.witness || 0) + '</strong></div>'
    + '<div style="font-size:.7rem;color:' + tone(t.factionHeat) + ';">Faction Heat: <strong>' + Number(t.factionHeat || 0) + '</strong></div>'
    + '</div>'
    + timelineHtml
    + '</div>';
}

function buildSolarCycleWitnessVowRecapHtml(sc, limit) {
  var state = sc || ensureSolarCycleState();
  var qs = getSolarCycleQuestScheduler(state);
  var maxRows = Math.max(3, Number(limit || 5));
  var vectors = qs && qs.npcVectors && typeof qs.npcVectors === 'object'
    ? Object.keys(qs.npcVectors).map(function (k) { return qs.npcVectors[k]; }).filter(function (v) { return v && typeof v === 'object'; })
    : [];

  var ledger = [];
  vectors.forEach(function (vec) {
    var rows = Array.isArray(vec.promiseLedger) ? vec.promiseLedger : [];
    rows.forEach(function (row) {
      if (!row || typeof row !== 'object') return;
      if (String(row.status || '') !== 'kept' && String(row.status || '') !== 'broken') return;
      ledger.push({
        npcName: String(vec.npcName || row.npcName || 'Unknown Witness'),
        region: String(vec.region || row.region || ''),
        status: String(row.status || ''),
        title: String(row.title || 'Quest'),
        dayLabel: String(row.dayLabel || ''),
        note: String(row.note || ''),
        ts: Number(row.ts || 0)
      });
    });
  });
  ledger.sort(function (a, b) { return Number(b.ts || 0) - Number(a.ts || 0); });

  var recentHtml = ledger.length
    ? ledger.slice(0, maxRows).map(function (row) {
      var tone = row.status === 'kept' ? 'var(--green2)' : 'var(--red2)';
      var tag = row.status === 'kept' ? 'KEPT' : 'BROKEN';
      return '<div style="border-bottom:1px solid var(--border2);padding:.22rem 0;">'
        + '<div style="font-size:.73rem;color:var(--text2);line-height:1.45;">'
        + '<strong style="color:' + tone + ';">[' + tag + ']</strong> '
        + escapeSolarCycleHtml(row.npcName) + ' · ' + escapeSolarCycleHtml(row.title)
        + '</div>'
        + '<div style="font-size:.68rem;color:var(--muted2);line-height:1.45;">'
        + escapeSolarCycleHtml(row.dayLabel || '')
        + (row.region ? (' · ' + escapeSolarCycleHtml(String(row.region).toUpperCase())) : '')
        + (row.note ? (' · ' + escapeSolarCycleHtml(row.note)) : '')
        + '</div>'
        + '</div>';
    }).join('')
    : '<div style="font-size:.73rem;color:var(--muted2);">No vow outcomes logged yet. Promise memory begins after your next witness resolution.</div>';

  var nearFlip = [];
  vectors.forEach(function (vec) {
    var pseudoQuest = { npcName: vec.npcName, region: vec.region };
    var stance = evaluateSolarCycleNpcStance(state, pseudoQuest, '');
    var affinity = Number(vec.affinity || 0);
    var allyThreshold = Number(stance.dynamicAllyThreshold || 3);
    var betrayalThreshold = Number(stance.dynamicBetrayalThreshold || -3);
    var allyGap = allyThreshold - affinity;
    var betrayalGap = affinity - betrayalThreshold;
    if (!stance.allyPotential && allyGap === 1) {
      nearFlip.push({
        npcName: String(vec.npcName || 'Unknown Witness'),
        region: String(vec.region || ''),
        type: 'ally',
        detail: '1 trust step from ally flip (' + affinity + ' -> ' + allyThreshold + ')'
      });
    }
    if (!stance.betrayalPotential && betrayalGap === 1) {
      nearFlip.push({
        npcName: String(vec.npcName || 'Unknown Witness'),
        region: String(vec.region || ''),
        type: 'betrayal',
        detail: '1 stress step from betrayal flip (' + affinity + ' -> ' + betrayalThreshold + ')'
      });
    }
  });

  var nearFlipHtml = nearFlip.length
    ? nearFlip.slice(0, 6).map(function (item) {
      var tone = item.type === 'ally' ? 'var(--teal)' : 'var(--red2)';
      var tag = item.type === 'ally' ? 'ALLY WATCH' : 'BETRAYAL WATCH';
      return '<div style="font-size:.69rem;color:' + tone + ';line-height:1.45;border-bottom:1px solid var(--border2);padding:.18rem 0;">'
        + '<strong>' + tag + ':</strong> '
        + escapeSolarCycleHtml(item.npcName)
        + (item.region ? (' [' + escapeSolarCycleHtml(String(item.region).toUpperCase()) + ']') : '')
        + ' · ' + escapeSolarCycleHtml(item.detail)
        + '</div>';
    }).join('')
    : '<div style="font-size:.69rem;color:var(--muted2);line-height:1.45;">No NPCs are one step from a trust flip right now.</div>';

  return '<div style="background:var(--surface2);border:1px solid var(--border2);padding:.65rem .75rem;margin-bottom:.6rem;">'
    + '<div style="font-size:.82rem;color:var(--gold2);margin-bottom:.22rem;"><strong>Witness Vow Recap</strong></div>'
    + '<div style="font-size:.74rem;color:var(--muted2);line-height:1.5;margin-bottom:.3rem;">Top 5 promise outcomes (kept/broken) and witnesses closest to alliance or betrayal flips.</div>'
    + '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:.45rem;">'
    + '<div>'
    + '<div style="font-size:.71rem;color:var(--teal);margin-bottom:.2rem;">Recent Promise Outcomes</div>'
    + recentHtml
    + '</div>'
    + '<div>'
    + '<div style="font-size:.71rem;color:var(--gold2);margin-bottom:.2rem;">Threshold Flip Watch</div>'
    + nearFlipHtml
    + '</div>'
    + '</div>'
    + '</div>';
}

function getSolarCycleEffectiveArc(sc) {
  var state = sc || ensureSolarCycleState();
  if (!state) return 'relic';
  var scarArc = state.timeFracture && state.timeFracture.scarFlags
    ? String(state.timeFracture.scarFlags.echoArc || '')
    : '';
  if (SOLAR_CYCLE_ARCS.indexOf(scarArc) >= 0) return scarArc;
  return SOLAR_CYCLE_ARCS.indexOf(state.activeArc) >= 0 ? state.activeArc : 'relic';
}

function getSolarCycleFractureMarkerText(activeArc, tier) {
  if (tier === 'early') return 'Time fracture echo: witnesses meet you before your arrival and warn that day 100 already failed once.';
  if (tier === 'mid') return 'The keeper repeats your future answers and asks which ending you are trying to prevent.';
  if (tier === 'late') return 'The lighthouse is gone, but your own voice broadcasts competing instructions for survival.';
  return 'The beam speaks in verdicts from failed timelines. Every rewind now changes how the world can end.';
}

function getSolarCycleRewindCap(sc) {
  var state = sc || ensureSolarCycleState();
  if (!state) return 0;
  var elapsed = Math.max(0, Number(state.daysElapsed || 0));
  return elapsed >= 7 ? 7 : 0;
}

function getSolarCycleRewindOptions() {
  var sc = ensureSolarCycleState();
  if (!sc || !sc.storyModeEnabled || !sc.enabled) return [];
  if (!sc.timeFracture || Number(sc.timeFracture.charges || 0) <= 0) return [];
  var cap = getSolarCycleRewindCap(sc);
  if (cap < 7) return [];
  return [7];
}

function getSolarCycleStageById(stageId) {
  var id = String(stageId || '');
  for (var i = 0; i < NEW_SUN_ARC_STAGES.length; i++) {
    if (NEW_SUN_ARC_STAGES[i].id === id) return NEW_SUN_ARC_STAGES[i];
  }
  return null;
}

function getPendingSolarCycleBranch(sc) {
  var state = sc || ensureSolarCycleState();
  if (!state) return '';
  var progress = state.arcProgress || {};
  for (var i = 0; i < NEW_SUN_ARC_STAGES.length; i++) {
    var stage = NEW_SUN_ARC_STAGES[i];
    if (!stage.branchPoint) continue;
    if (progress.completedStageIds && progress.completedStageIds[stage.id] && !progress.branchChoices[stage.branchPoint]) {
      return stage.branchPoint;
    }
  }
  return '';
}

function syncSolarCycleArcProgressFromCompleted(notify) {
  var sc = ensureSolarCycleState();
  if (!sc) return null;
  var progress = sc.arcProgress || {};
  var completed = (S.completedMissions || []).filter(function (m) {
    return m && m.missionType === 'solar_cycle_arc' && getSolarCycleStageById(m.templateId);
  });

  completed.forEach(function (m) {
    progress.completedStageIds[m.templateId] = true;
  });

  var nextIndex = 0;
  while (nextIndex < NEW_SUN_ARC_STAGES.length && progress.completedStageIds[NEW_SUN_ARC_STAGES[nextIndex].id]) {
    nextIndex++;
  }

  if (nextIndex > progress.stageIndex) {
    progress.history.push('Arc advanced to stage ' + nextIndex + ' on day ' + Number(sc.daysElapsed || 0) + '.');
    if (notify && typeof showNotif === 'function') {
      showNotif('New Sun arc advanced: ' + nextIndex + '/' + NEW_SUN_ARC_STAGES.length + '.', 'good');
    }
  }
  progress.stageIndex = nextIndex;
  progress.lastSyncedCompletedCount = completed.length;

  var hasActiveArcMission = (S.activeMissions || []).some(function (m) {
    return m && m.missionType === 'solar_cycle_arc' && getSolarCycleStageById(m.templateId);
  });
  if (!hasActiveArcMission) progress.activeMissionId = null;

  return progress;
}

function postNextSolarCycleArcMission() {
  ensureStarsState();
  var sc = ensureSolarCycleState();
  if (!sc || !sc.storyModeEnabled || !sc.enabled) {
    if (typeof showNotif === 'function') showNotif('Start a New Sun run first.', 'warn');
    return null;
  }
  if (typeof window.createMission !== 'function') {
    if (typeof showNotif === 'function') showNotif('Mission system unavailable.', 'warn');
    return null;
  }

  var progress = syncSolarCycleArcProgressFromCompleted(true);
  var pendingBranch = getPendingSolarCycleBranch(sc);
  if (pendingBranch) {
    if (typeof showNotif === 'function') showNotif('Resolve the pending branch choice before posting the next arc mission.', 'warn');
    return null;
  }

  if (progress.stageIndex >= NEW_SUN_ARC_STAGES.length) {
    if (typeof showNotif === 'function') showNotif('All New Sun arc missions are completed. Resolve the ending.', 'info');
    return null;
  }

  var stage = NEW_SUN_ARC_STAGES[progress.stageIndex];
  var existing = (S.activeMissions || []).find(function (m) {
    return m && m.missionType === 'solar_cycle_arc' && m.templateId === stage.id;
  });
  if (existing) {
    progress.activeMissionId = existing.id;
    if (typeof showNotif === 'function') showNotif('Arc mission already active: ' + stage.title + '.', 'info');
    return existing;
  }

  var faction = {
    gain: stage.factionGain,
    lose: stage.factionLose,
    gainName: stage.factionGainName,
    loseName: stage.factionLoseName
  };
  var mission = window.createMission(
    stage.issuer,
    stage.title,
    stage.difficulty,
    stage.location,
    stage.region,
    faction,
    {
      missionType: 'solar_cycle_arc',
      storyTheme: 'new_sun',
      templateId: stage.id,
      checkpoints: stage.checkpoints,
      stepNames: stage.stepNames,
      contractPathway: 'new_sun_arc'
    }
  );

  if (!mission) return null;
  progress.activeMissionId = mission.id;
  progress.postedStageIds[stage.id] = true;
  sc.prophecyTrack.push('Arc mission posted: ' + stage.title + '.');
  if (typeof showNotif === 'function') showNotif('New Sun mission posted: ' + stage.title + '.', 'good');
  if (typeof window.renderMissionTracker === 'function') window.renderMissionTracker();
  if (typeof window.renderNewSunModePanel === 'function') window.renderNewSunModePanel();
  return mission;
}

function chooseSolarCycleBranch(branchId, choiceId) {
  ensureStarsState();
  var sc = ensureSolarCycleState();
  if (!sc || !sc.storyModeEnabled || !sc.enabled) return false;

  var bId = String(branchId || '');
  var cId = String(choiceId || '');
  var branch = NEW_SUN_BRANCH_POINTS[bId];
  if (!branch || !branch.choices || !branch.choices[cId]) return false;

  var pending = getPendingSolarCycleBranch(sc);
  if (pending && pending !== bId) {
    if (typeof showNotif === 'function') showNotif('Resolve branch choices in sequence.', 'warn');
    return false;
  }

  var choice = branch.choices[cId];
  sc.arcProgress.branchChoices[bId] = cId;
  sc.worldTilt = Math.max(0, Math.min(4, Number(sc.worldTilt || 0) + Number(choice.worldTiltDelta || 0)));
  if (sc.timeFracture && sc.timeFracture.scarFlags) {
    sc.timeFracture.scarFlags.paradoxStrain = Math.max(0, Number(sc.timeFracture.scarFlags.paradoxStrain || 0) + Number(choice.paradoxDelta || 0));
  }
  if (choice.prophecy) sc.prophecyTrack.push(choice.prophecy);

  if (Number(choice.tmwDelta || 0) !== 0) {
    if (typeof changeCounter === 'function') {
      changeCounter('tmw', Number(choice.tmwDelta || 0));
    } else {
      S.tmw = Math.max(0, Number(S.tmw || 0) + Number(choice.tmwDelta || 0));
    }
  }

  S.storyline = S.storyline || {};
  S.storyline.flags = S.storyline.flags || {};
  S.storyline.flags['newSunBranch_' + bId] = cId;

  var branchConsequenceDeltas = {
    stability: Number(choice.worldTiltDelta || 0) < 0 ? 1 : (Number(choice.worldTiltDelta || 0) > 0 ? -1 : 0),
    scarcity: 0,
    corruption: Number(choice.paradoxDelta || 0) > 0 ? 1 : 0,
    rumor: Number(choice.paradoxDelta || 0) > 0 ? 1 : 0,
    witness: Number(choice.worldTiltDelta || 0) < 0 ? 1 : -1,
    factionHeat: Number(choice.worldTiltDelta || 0) > 0 ? 1 : 0
  };
  if (bId === 'tide_compact' && cId === 'bind') {
    branchConsequenceDeltas.scarcity = -1;
    branchConsequenceDeltas.witness = Number(branchConsequenceDeltas.witness || 0) + 1;
  }
  if (bId === 'tide_compact' && cId === 'draft') {
    branchConsequenceDeltas.scarcity = 1;
    branchConsequenceDeltas.factionHeat = Number(branchConsequenceDeltas.factionHeat || 0) + 1;
  }
  recordWorldConsequence({
    system: 'newsun',
    title: 'Branch locked: ' + String(branch.title || bId),
    detail: String(choice.summary || choice.label || ''),
    region: (bId === 'keeper_oath' ? 'province' : (bId === 'tide_compact' ? 'sea' : 'galaxy')),
    severity: Number(choice.worldTiltDelta || 0) > 0 ? 'high' : 'medium',
    deltas: branchConsequenceDeltas
  });

  if (bId === 'keeper_oath' && cId === 'preserve') recordSolarCycleIrreversibleTag('branch_preserve_success', { branch: bId, choice: cId });
  if (bId === 'keeper_oath' && cId === 'break') recordSolarCycleIrreversibleTag('branch_break_success', { branch: bId, choice: cId });
  if (bId === 'tide_compact' && cId === 'bind') recordSolarCycleIrreversibleTag('branch_bind_success', { branch: bId, choice: cId });
  if (bId === 'tide_compact' && cId === 'draft') recordSolarCycleIrreversibleTag('branch_draft_success', { branch: bId, choice: cId });
  if (bId === 'final_signal' && cId === 'open') recordSolarCycleIrreversibleTag('branch_open_success', { branch: bId, choice: cId });
  if (bId === 'final_signal' && cId === 'crown') recordSolarCycleIrreversibleTag('branch_crown_success', { branch: bId, choice: cId });
  if (bId === 'final_signal' && cId === 'sever') recordSolarCycleIrreversibleTag('branch_sever_success', { branch: bId, choice: cId });

  if (typeof showNotif === 'function') showNotif('Branch chosen: ' + choice.label + '.', 'info');
  if (typeof window.renderNewSunModePanel === 'function') window.renderNewSunModePanel();
  if (typeof window.renderStorylinePanel === 'function') window.renderStorylinePanel();
  return true;
}

function getSolarCycleOutcomeProfile(sc) {
  var state = sc || ensureSolarCycleState();
  var progress = state && state.arcProgress ? state.arcProgress : {};
  var branches = progress.branchChoices || {};
  var results = progress.stageResults || {};
  var flags = (S && S.storyline && S.storyline.flags) ? S.storyline.flags : {};
  var playstyle = state && state.playstyle ? state.playstyle : {};
  var stageSummary = { completed: 0, success: 0, failure: 0, missed: 0 };

  NEW_SUN_ARC_STAGES.forEach(function (stage) {
    if (!progress.completedStageIds || !progress.completedStageIds[stage.id]) return;
    stageSummary.completed += 1;
    if (results[stage.id] && results[stage.id].success === false) stageSummary.failure += 1;
    else stageSummary.success += 1;
  });

  var allStagesDone = stageSummary.completed >= NEW_SUN_ARC_STAGES.length;
  var forcedFinale = !!(state && state.endingFlags && state.endingFlags.forcedFinaleTriggered);
  if (forcedFinale && !allStagesDone) {
    stageSummary.missed = Math.max(0, NEW_SUN_ARC_STAGES.length - stageSummary.completed);
  }

  var strain = (state && state.timeFracture && state.timeFracture.scarFlags)
    ? Number(state.timeFracture.scarFlags.paradoxStrain || 0)
    : 0;
  var rewinds = state && state.timeFracture ? Number(state.timeFracture.rewindsUsed || 0) : 0;
  var worldTilt = state ? Number(state.worldTilt || 0) : 0;
  var mercyRoute = branches.keeper_oath === 'preserve' && branches.tide_compact === 'bind';
  var dominionRoute = branches.keeper_oath === 'break' || branches.tide_compact === 'draft' || branches.final_signal === 'crown';
  var openRoute = branches.final_signal === 'open' || !!flags.newSunSharedDawn;
  var severRoute = branches.final_signal === 'sever' || !!flags.newSunSignalSevered;
  var trueIgnition = !!flags.newSunTrueIgnition;
  var crowned = branches.final_signal === 'crown' || !!flags.newSunCrowned;
  var warFleet = !!flags.newSunWarFleet || branches.tide_compact === 'draft';
  var archiveSecured = !!(flags.newSunArchiveAudit || flags.newSunArchiveHack || flags.newSunSmuggledArchive || flags.newSunWardBroken);
  var witnessNetwork = !!(flags.newSunSafeCurrents || flags.newSunDeadCharts || flags.newSunFlavorCurrent);
  var seaCovenant = !!(flags.newSunSafeCurrents || flags.newSunDeadCharts);
  var archiveTruth = !!(flags.newSunArchiveAudit || flags.newSunArchiveHack);
  var timeTouched = rewinds >= 2 || Number(flags.solarParadoxMarks || 0) >= 2;
  var ignoredOmens = Number(playstyle.ignore || 0);
  var intervenedOmens = Number(playstyle.intervene || 0);
  var observedOmens = Number(playstyle.observe || 0);

  return {
    state: state,
    branches: branches,
    flags: flags,
    stageSummary: stageSummary,
    allStagesDone: allStagesDone,
    forcedFinale: forcedFinale,
    strain: strain,
    rewinds: rewinds,
    worldTilt: worldTilt,
    mercyRoute: mercyRoute,
    dominionRoute: dominionRoute,
    openRoute: openRoute,
    severRoute: severRoute,
    trueIgnition: trueIgnition,
    crowned: crowned,
    warFleet: warFleet,
    archiveSecured: archiveSecured,
    archiveTruth: archiveTruth,
    witnessNetwork: witnessNetwork,
    seaCovenant: seaCovenant,
    timeTouched: timeTouched,
    ignoredOmens: ignoredOmens,
    intervenedOmens: intervenedOmens,
    observedOmens: observedOmens,
    effectiveArc: String(getSolarCycleEffectiveArc(state) || 'relic')
  };
}

function ensureSolarCycleLegacyState() {
  if (typeof S === 'undefined') return null;
  S.solarCycleLegacy = S.solarCycleLegacy || {};
  if (!S.solarCycleLegacy.irreversibleTags || typeof S.solarCycleLegacy.irreversibleTags !== 'object') {
    S.solarCycleLegacy.irreversibleTags = {};
  }
  if (!Array.isArray(S.solarCycleLegacy.history)) S.solarCycleLegacy.history = [];
  if (!S.solarCycleLegacy.raidsById || typeof S.solarCycleLegacy.raidsById !== 'object') S.solarCycleLegacy.raidsById = {};
  if (!Array.isArray(S.solarCycleLegacy.activeRaidIds)) S.solarCycleLegacy.activeRaidIds = [];
  if (!Array.isArray(S.solarCycleLegacy.completedRaidIds)) S.solarCycleLegacy.completedRaidIds = [];
  if (!Array.isArray(S.solarCycleLegacy.missedRaidIds)) S.solarCycleLegacy.missedRaidIds = [];
  if (typeof S.solarCycleLegacy.lastRaidSyncStamp !== 'number') S.solarCycleLegacy.lastRaidSyncStamp = -1;
  if (typeof S.solarCycleLegacy.nextRaidEligibleStamp !== 'number') S.solarCycleLegacy.nextRaidEligibleStamp = 0;
  if (typeof S.solarCycleLegacy.raidCounter !== 'number') S.solarCycleLegacy.raidCounter = 0;
  if (typeof S.solarCycleLegacy.medals !== 'number') S.solarCycleLegacy.medals = 0;
  if (typeof S.solarCycleLegacy.raidPoints !== 'number') S.solarCycleLegacy.raidPoints = 0;
  if (!S.solarCycleLegacy.raidRelics || typeof S.solarCycleLegacy.raidRelics !== 'object') S.solarCycleLegacy.raidRelics = {};
  if (!S.solarCycleLegacy.raidTree || typeof S.solarCycleLegacy.raidTree !== 'object') {
    S.solarCycleLegacy.raidTree = { scout_network: false, bulwark_drill: false, trophy_claim: false };
  }
  if (!S.solarCycleLegacy.raidTreeRanks || typeof S.solarCycleLegacy.raidTreeRanks !== 'object') {
    S.solarCycleLegacy.raidTreeRanks = {};
  }
  if (typeof S.solarCycleLegacy.raidTree.scout_network !== 'boolean') S.solarCycleLegacy.raidTree.scout_network = false;
  if (typeof S.solarCycleLegacy.raidTree.bulwark_drill !== 'boolean') S.solarCycleLegacy.raidTree.bulwark_drill = false;
  if (typeof S.solarCycleLegacy.raidTree.trophy_claim !== 'boolean') S.solarCycleLegacy.raidTree.trophy_claim = false;
  return S.solarCycleLegacy;
}

