function getGalaxyMerchantLootPool() {
  if (typeof SHOP_DATA === 'undefined' || !SHOP_DATA) return [];
  const keys = ['weapons', 'melee_exp', 'ranged_exp', 'armor', 'armor_exp', 'items', 'toolkits', 'essentials', 'remedies', 'scrolls', 'weapon_mods', 'tradegoods', 'cosmic', 'space_armor', 'exocrafts', 'starship_fuel'];
  const pool = [];
  keys.forEach((k) => {
    const list = SHOP_DATA[k];
    if (Array.isArray(list)) {
      list.forEach((it) => {
        if (it && it.name) pool.push(it.name);
      });
    }
  });
  return pool;
}

function rollGalaxyMerchantLoot(fallbackPool) {
  let result = '';
  if (typeof rollForLoot === 'function') {
    try {
      const rolled = rollForLoot('easy');
      if (Array.isArray(rolled) && rolled.length) result = pick(rolled);
    } catch (err) {}
  }
  if (!result) {
    const pool = getGalaxyMerchantLootPool();
    if (pool.length) result = pick(pool);
  }
  if (!result) {
    const fallback = Array.isArray(fallbackPool) && fallbackPool.length ? fallbackPool : MYSTERY_TRADE;
    result = pick(fallback);
  }
  return result;
}

function loseGamePhases(count) {
  ensureStarsState();
  let n = Math.max(1, parseInt(count, 10) || 1);
  while (n > 0) {
    if ((S.gameDate.phase || 0) < getActiveDayPhases().length - 1) {
      S.gameDate.phase = (S.gameDate.phase || 0) + 1;
    } else {
      S.gameDate.phase = 0;
      advanceDay(1, true);
    }
    n -= 1;
  }
  updateDateUI();
}

function resolveGalaxySkillCheck(primaryKey, secondaryKey, dd, label) {
  const normalizedPrimary = normalizeSolarCycleActionStat(primaryKey);
  const normalizedSecondary = secondaryKey ? normalizeSolarCycleActionStat(secondaryKey) : null;
  const p = (typeof getEffectiveDie === 'function') ? getEffectiveDie(normalizedPrimary) : ((S.stats && S.stats[normalizedPrimary]) || 4);
  const s = normalizedSecondary ? ((typeof getEffectiveDie === 'function') ? getEffectiveDie(normalizedSecondary) : ((S.stats && S.stats[normalizedSecondary]) || 4)) : 0;
  const die = Math.max(p || 4, s || 0, 4);
  const primaryLabel = String(normalizedPrimary || 'action').charAt(0).toUpperCase() + String(normalizedPrimary || 'action').slice(1);
  const secondaryLabel = normalizedSecondary ? (String(normalizedSecondary).charAt(0).toUpperCase() + String(normalizedSecondary).slice(1)) : '';
  let actionLabel = primaryLabel;
  if (normalizedSecondary) {
    if (Number(p || 0) > Number(s || 0)) actionLabel = primaryLabel;
    else if (Number(s || 0) > Number(p || 0)) actionLabel = secondaryLabel;
    else actionLabel = primaryLabel + '/' + secondaryLabel;
  }
  const invBonus = (typeof collectInventoryBonusesForStat === 'function') ? collectInventoryBonusesForStat(normalizedPrimary) : { advDice: [], flat: 0, addValor: 0 };
  const rollMod = (S && S.rollMod && typeof S.rollMod === 'object') ? S.rollMod : { advDice: [], flat: 0 };
  const actionAdvDice = []
    .concat(Array.isArray(invBonus.advDice) ? invBonus.advDice : [])
    .concat(Array.isArray(rollMod.advDice) ? rollMod.advDice : []);
  const action = (typeof rollWithAdvantage === 'function')
    ? rollWithAdvantage(die, actionAdvDice, { type: 'action', major: true, label: String(label || actionLabel) })
    : { total: explodingRoll(die, { type: 'action', major: true, label: String(label || actionLabel) }).total };
  let actionTotal = action.total + Number(invBonus.flat || 0) + Number(rollMod.flat || 0);
  const queuedValor = (typeof consumeQueuedRollModValorDice === 'function')
    ? consumeQueuedRollModValorDice(String(label || actionLabel) + ' Queued Valor')
    : { total: 0 };
  actionTotal += Number(queuedValor.total || 0);
  const valorDie = (typeof getEffectiveDie === 'function') ? getEffectiveDie('valor') : ((S.stats && S.stats.valor) || 4);
  for (let i = 0; i < Number(invBonus.addValor || 0); i++) {
    actionTotal += explodingRoll(valorDie, { type: 'action', major: true, label: String(label || actionLabel) + ' Item V.D. #' + String(i + 1) }).total;
  }
  const dread = explodingRoll(dd, { type: 'dread', major: true, label: 'Dread d' + String(dd) });
  const success = actionTotal >= dread.total;
  return {
    success,
    delta: Math.max(1, Math.abs(actionTotal - dread.total)),
    actionTotal,
    dreadTotal: dread.total,
    actionDie: die,
    dreadDie: dd,
    statKey: normalizedPrimary,
    secondaryStatKey: normalizedSecondary,
    text: `${label}: ${actionLabel} d${die}=${actionTotal} vs Dread d${dd}=${dread.total}`,
  };
}

function formatStarsCheckLabel(label) {
  return String(label || 'Lead')
    .split('/')
    .map(function(part) {
      return String(part || '')
        .trim()
        .split(/\s+/)
        .filter(Boolean)
        .map(function(word) {
          return word.charAt(0).toUpperCase() + word.slice(1);
        })
        .join(' ');
    })
    .join('/');
}

function runStarsActionDreadCheck(config) {
  const cfg = config && typeof config === 'object' ? config : {};
  const statKey = normalizeSolarCycleActionStat(cfg.statKey || 'valor');
  const secondaryKey = cfg.secondaryKey ? normalizeSolarCycleActionStat(cfg.secondaryKey) : null;
  const statLabel = String(cfg.statLabel || (statKey.charAt(0).toUpperCase() + statKey.slice(1) + (secondaryKey ? ('/' + secondaryKey.charAt(0).toUpperCase() + secondaryKey.slice(1)) : '')));
  const dreadDie = Math.max(4, Number(cfg.dreadDie || 6));
  const primaryDie = (typeof getEffectiveDie === 'function') ? getEffectiveDie(statKey) : ((S.stats && S.stats[statKey]) || 4);
  const secondaryDie = secondaryKey ? ((typeof getEffectiveDie === 'function') ? getEffectiveDie(secondaryKey) : ((S.stats && S.stats[secondaryKey]) || 4)) : 0;
  const actionDie = Math.max(4, Number(primaryDie || 4), Number(secondaryDie || 0));
  const onResolve = (typeof cfg.onResolve === 'function') ? cfg.onResolve : null;
  if (isGlobalManualRollMode()) {
    openGlobalManualActionDreadPrompt({
      title: String(cfg.title || ('Manual Roll - ' + statLabel)),
      context: String(cfg.context || cfg.label || (statLabel + ' vs DD' + dreadDie)),
      statKey: statKey,
      statLabel: statLabel,
      actionDie: actionDie,
      dreadDie: dreadDie,
      onResolve: onResolve
    });
    return true;
  }
  const check = resolveGalaxySkillCheck(statKey, secondaryKey, dreadDie, String(cfg.label || (statLabel + ' Check')));
  if (onResolve) {
    onResolve({
      success: !!check.success,
      text: check.text,
      manual: false,
      pushLuck: false,
      statKey: statKey,
      statLabel: statLabel,
      actionDie: Number(check.actionDie || actionDie),
      dreadDie: Number(check.dreadDie || dreadDie),
      actionTotal: Number(check.actionTotal || 0),
      dreadTotal: Number(check.dreadTotal || 0),
      delta: Math.max(1, Number(check.delta || 1))
    });
  }
  return true;
}

