    features: ['Phase Anchor', 'Resonance Gate', 'Light Well', 'Pulse Observatory'],
    roles: ['Resonance Monk', 'Signal Oracle', 'Phase Surveyor'],
    taskFocus: ['anomaly mapping', 'signal tuning', 'artifact anchoring'],
