function getHighestFactionRenown() {
  ensureStarsState();
  return Object.values(S.factionRenown || {}).reduce((mx, val) => Math.max(mx, Number(val) || 0), 0);
}

function hasHoldingFactionThreshold() {
  return getHighestFactionRenown() >= 9;
}

function tryUnlockHoldingFromFaction() {
  if (!hasHoldingFactionThreshold()) return;
  if (typeof renderHoldingUI === 'function') {
    try { renderHoldingUI(); } catch (err) {}
  }
  if (typeof renderMissionBoard === 'function') {
    try { renderMissionBoard(); } catch (err) {}
  }
}

function patchStarsCrossSystemHooks() {
  const baseSetStress = typeof setStress === 'function' ? setStress : null;
  if (baseSetStress && !window._starsSetStressPatched) {
    window._starsSetStressPatched = true;
    setStress = function(value) {
      const defendBefore = (typeof getEffectiveDie === 'function') ? getEffectiveDie('defend') : (S.stats && S.stats.defend ? S.stats.defend : 4);
      const maxHealthBefore = defendBefore * 2;
      const prevHealth = (typeof S.health === 'number') ? S.health : (S.stress || 0);
      const out = baseSetStress.apply(this, arguments);
      S.health = S.stress || 0;
      updateHealthUI();
      if (prevHealth < maxHealthBefore && S.health >= maxHealthBefore) {
        showNotif('Health at maximum — near death. Rolling Scar check.', 'warn');
        handleScarEncounter({ source: 'health-cap' });
      }
      return out;
    };
  }

  const baseStartCombat = typeof startCombat === 'function' ? startCombat : null;
  if (baseStartCombat && !window._starsStartCombatPatched) {
    window._starsStartCombatPatched = true;
    startCombat = function() {
      const out = baseStartCombat.apply(this, arguments);
      if ((S.mentalStress || 0) >= 10) {
        S.tmw = Math.max(0, (S.tmw || 0) - 1);
        if (typeof updateTMWPool === 'function') updateTMWPool();
        showNotif('Fraying: -1 TMW at scene start.', 'warn');
      }
      return out;
    };
  }

  const baseRollCheck = typeof rollCheck === 'function' ? rollCheck : null;
  if (baseRollCheck && !window._starsRollCheckPatched) {
    window._starsRollCheckPatched = true;
    rollCheck = function() {
      const beforeCount = (S && Array.isArray(S.injuries)) ? S.injuries.length : 0;
      const out = baseRollCheck.apply(this, arguments);
      const noteEl = document.getElementById('resNote');
      const noteText = noteEl ? String(noteEl.textContent || '') : '';
      if (noteText.indexOf('Dread die exploded') >= 0) {
        registerIncomingCritical('Dread Critical');
      }
      const afterCount = (S && Array.isArray(S.injuries)) ? S.injuries.length : beforeCount;
      if (afterCount > beforeCount) updateInjuriesUI();
      return out;
    };
  }

  const baseResolveMission = typeof resolveMission === 'function' ? resolveMission : null;
  if (baseResolveMission && !window._starsResolveMissionPatched) {
    window._starsResolveMissionPatched = true;
    resolveMission = function(missionId, success) {
      const out = baseResolveMission.apply(this, arguments);
      if (success) tryUnlockHoldingFromFaction();
      return out;
    };
  }

  const baseExplodingRoll = typeof explodingRoll === 'function' ? explodingRoll : null;
  if (baseExplodingRoll && !window._starsExplodingRollPatched) {
    window._starsExplodingRollPatched = true;
    explodingRoll = function(n) {
      const out = baseExplodingRoll.apply(this, arguments);
      const penalty = getScarRollPenalty();
      if (penalty) {
        out.baseTotal = Number(out.total || 0);
        out.rollPenalty = penalty;
        out.total = Math.max(0, out.total + penalty);
      } else if (typeof out.baseTotal === 'undefined') {
        out.baseTotal = Number(out.total || 0);
        out.rollPenalty = 0;
      }
      return out;
    };
  }

  const baseResolveSeaEncounter = typeof resolveSeaEncounter === 'function' ? resolveSeaEncounter : null;
  if (baseResolveSeaEncounter && !window._starsResolveSeaEncounterPatched) {
    window._starsResolveSeaEncounterPatched = true;
    resolveSeaEncounter = function(action) {
      ensureStarsState();
      if (action === 'flee' && S.scarState && S.scarState.cannotEscapeCombat) {
        showNotif('Scar effect: you cannot flee combat encounters.', 'warn');
        return;
      }
      return baseResolveSeaEncounter.apply(this, arguments);
    };
  }

  const baseAddTMWOnFail = typeof addTMWOnFail === 'function' ? addTMWOnFail : null;
  if (baseAddTMWOnFail && !window._starsAddTMWOnFailPatched) {
    window._starsAddTMWOnFailPatched = true;
    addTMWOnFail = function() {
      const out = baseAddTMWOnFail.apply(this, arguments);
      ensureStarsState();
      if (S.scarState && S.scarState.loseHealthOnFailedRoll && typeof changeHealth === 'function') {
        changeHealth(1);
        showNotif('Scar effect: lingering wound causes +1 Health damage on failure.', 'warn');
      }
      return out;
    };
  }

  const baseSetContext = typeof setContext === 'function' ? setContext : null;
  if (baseSetContext && !window._starsSetContextPatched) {
    window._starsSetContextPatched = true;
    setContext = function(ctx, btn) {
      const out = baseSetContext.apply(this, arguments);
      syncNavalStateForContext(ctx);
      return out;
    };
  }

  const baseRenderNaval = typeof renderNaval === 'function' ? renderNaval : null;
  if (baseRenderNaval && !window._starsRenderNavalPatched) {
    window._starsRenderNavalPatched = true;
    renderNaval = function() {
      const out = baseRenderNaval.apply(this, arguments);
      syncSpaceCombatStateFromNaval();
      applySpaceNavalPresentation();
      return out;
    };
  }
}

function guardCampaignSharedWorldMutation(errorText, requestDetails) {
  if (!window.campaignSystem || typeof window.campaignSystem.guardSharedWorldMutation !== 'function') return true;
  return window.campaignSystem.guardSharedWorldMutation(
    errorText || 'Only the GM can change the shared world state in Campaign mode.',
    requestDetails || null
  );
}

function syncCampaignSharedWorldSoon(reason) {
  if (!window.campaignSystem || typeof window.campaignSystem.syncSharedSilent !== 'function') return;
  const campaignState = (typeof window.campaignSystem.getState === 'function') ? window.campaignSystem.getState() : null;
  if (!campaignState || !campaignState.code || campaignState.role !== 'gm') return;
  setTimeout(function() {
    try {
      const out = window.campaignSystem.syncSharedSilent(reason || 'shared-world');
      if (out && typeof out.catch === 'function') out.catch(function() {});
    } catch (_err) {}
  }, 0);
}

function rollStressReaction() {
  const r = roll(10);
  const entry = STRESS_REACTIONS[r - 1];
  const el = document.getElementById('stressReactionResult');
  if (el) el.innerHTML = `<div class="roll-badge">d10 = ${r}</div> ${entry}`;
  showNotif(`Stress Reaction: ${entry}`, 'warn');
}

