// ── SIDE STORY SYSTEM FUNCTIONS ────────────────────────────────────────────────

function ensureSolarCycleSideStories(sc) {
  var state = sc || ensureSolarCycleState();
  if (!state) return [];
  if (!Array.isArray(state.sideStories)) state.sideStories = [];
  return state.sideStories;
}

function getSolarCycleSideStoryById(storyId, sc) {
  var stories = ensureSolarCycleSideStories(sc);
  for (var i = 0; i < stories.length; i++) { if (stories[i].id === storyId) return stories[i]; }
  return null;
}

function getSolarCycleSideStoryBehaviorProfile(sc) {
  var state = sc || ensureSolarCycleState();
  var qs = getSolarCycleQuestScheduler(state);
  var style = state && state.playstyle ? state.playstyle : { observe: 0, intervene: 0, ignore: 0 };
  var approaches = qs && qs.approachStats ? qs.approachStats : { investigate: 0, fracture: 0, misled: 0, portal: 0 };
  var byStat = qs && qs.actionProfile && qs.actionProfile.byStat ? qs.actionProfile.byStat : {};
  var aggressiveStats = Number(byStat.strike || 0) + Number(byStat.shoot || 0) + Number(byStat.body || 0) + Math.floor(Number(byStat.control || 0) * 0.5);
  var investigativeStats = Number(byStat.mind || 0) + Number(byStat.spirit || 0) + Number(byStat.lead || 0) + Math.floor(Number(byStat.control || 0) * 0.4);
  var aggressiveScore = Number(style.intervene || 0) * 2 + Number(approaches.fracture || 0) * 2 + Number(approaches.misled || 0) + aggressiveStats;
  var investigativeScore = Number(style.observe || 0) * 2 + Number(approaches.investigate || 0) * 2 + Number(approaches.portal || 0) + investigativeStats;
  var bias = aggressiveScore - investigativeScore;
  var targetActive = 2;
  if (Number(state && state.daysElapsed || 0) >= 70) targetActive += 1;
  if (bias >= 5 || bias <= -5) targetActive += 1;
  targetActive = Math.max(2, Math.min(4, targetActive));
  return {
    aggressiveScore: aggressiveScore,
    investigativeScore: investigativeScore,
    bias: bias,
    targetActive: targetActive
  };
}

function getSolarCycleSideStorySpawnChance(profile, activeCount) {
  var p = profile || { bias: 0, targetActive: 2 };
  var count = Number(activeCount || 0);
  if (count <= 0) return 100;
  var chance = 55 + Math.min(25, Math.abs(Number(p.bias || 0)) * 3);
  if (count < Number(p.targetActive || 2)) chance += 18;
  return Math.max(30, Math.min(95, chance));
}

function pickSolarCycleSideStoryTemplateWeighted(eligible, state, profile, day, phase, storyCount) {
  if (!eligible || !eligible.length) return null;
  var totalWeight = 0;
  var weighted = eligible.map(function (t, idx) {
    var weight = 100;
    var kind = String(t.contentType || 'lore');
    if (kind === 'faction') {
      weight += Math.max(0, Number(profile && profile.bias || 0)) * 18;
    } else {
      weight += Math.max(0, Number(-(profile && profile.bias || 0) || 0)) * 18;
    }
    weight += (idx % 3) * 7;
    weight = Math.max(1, Math.floor(weight));
    totalWeight += weight;
    return { template: t, weight: weight };
  });
  var seed = seedSolarCycleMix(state, Number(day || 0) * 29 + Number(phase || 0) * 17 + Number(storyCount || 0) * 13);
  var pick = totalWeight > 0 ? (seed % totalWeight) : 0;
  for (var i = 0; i < weighted.length; i++) {
    pick -= weighted[i].weight;
    if (pick < 0) return weighted[i].template;
  }
  return weighted[0].template;
}

function expireSolarCycleSideStories(sc) {
  var state = sc || ensureSolarCycleState();
  if (!state) return;
  var stories = ensureSolarCycleSideStories(state);
  var day = Number(state.daysElapsed || 0);
  stories.forEach(function (story) {
    if (!story || !story.active || story.completed || story.failed) return;
    if (Number(day - Number(story.spawnDay || 0)) <= 10) return;
    story.active = false;
    story.failed = true;
    if (story.mapKey && S && S.missionTokens && S.missionTokens[String(story.mapKey)]) {
      delete S.missionTokens[String(story.mapKey)];
    }
  });
}

function maybeEnsureSolarCycleSideStoryLoop(sc) {
  var state = sc || ensureSolarCycleState();
  if (!state || !state.enabled || !state.storyModeEnabled) return null;
  expireSolarCycleSideStories(state);
  var stories = ensureSolarCycleSideStories(state);
  var profile = getSolarCycleSideStoryBehaviorProfile(state);
  var active = stories.filter(function (s) { return s && s.active && !s.completed && !s.failed; }).length;
  if (active >= Number(profile.targetActive || 2)) return null;
  return maybeSpawnSolarCycleSideStory(state, { force: active <= 0 });
}

function maybeSpawnSolarCycleSideStory(sc, opts) {
  var state = sc || ensureSolarCycleState();
  if (!state || !state.enabled || !state.storyModeEnabled) return null;
  var options = opts || {};
  var force = !!options.force;
  var stories = ensureSolarCycleSideStories(state);
  var day = Number(state.daysElapsed || 0);
  var phase = getSolarCyclePhaseIndex();
  if (!force && Number(state.sideStoryLastSpawnDay || -1) === day) return null;
  expireSolarCycleSideStories(state);
  var profile = getSolarCycleSideStoryBehaviorProfile(state);

  // Collect eligible templates (not already active/completed, spawn window matches)
  var active = stories.filter(function (s) { return s.active && !s.completed && !s.failed; });
  if (active.length >= Number(profile.targetActive || 3)) return null;

  var activeTemplateUse = {};
  stories.forEach(function (s) {
    if (s && s.active && !s.completed && !s.failed) activeTemplateUse[s.templateId] = true;
  });

  var eligible = SOLAR_CYCLE_SIDE_STORY_TEMPLATES.filter(function (t) {
    if (activeTemplateUse[t.id]) return false;
    if (day < t.spawnDay[0] || day > t.spawnDay[1]) return false;
    if (Array.isArray(t.spawnPhases) && t.spawnPhases.length && t.spawnPhases.indexOf(phase) < 0) return false;
    // Allow recurring side stories, but don't repeat the same template too quickly.
    var recent = stories.filter(function (s) {
      return s && s.templateId === t.id && Number(day - Number(s.spawnDay || 0)) < 9;
    });
    if (recent.length > 0) return false;
    return true;
  });
  if (!eligible.length) return null;

  var spawnChance = getSolarCycleSideStorySpawnChance(profile, active.length);
  if (!force) {
    var roll = seedSolarCycleMix(state, day * 7 + stories.length * 13 + phase) % 100;
    if (roll >= spawnChance) return null;
  }

  var template = pickSolarCycleSideStoryTemplateWeighted(eligible, state, profile, day, phase, stories.length);
  if (!template) return null;
  var story = {
    id: 'ss-' + String(template.id) + '-' + String(day) + '-' + String(Math.floor(Math.random() * 9999)),
    templateId: template.id,
    characterType: template.characterType,
    characterName: template.name,
    intro: template.intro,
    fateHint: template.fateHint,
    beatIndex: 0,
    active: true,
    completed: false,
    failed: false,
    spawnDay: day,
    spawnPhase: phase
  };
  stories.push(story);
  state.sideStoryLastSpawnDay = day;
  // Place a visible marker on the province map so the player can find the character.
  var _sideHex = null;
  var _sideKey = '';
  if (typeof S !== 'undefined' && S && S.missionTokens && typeof pickSolarCycleProvinceHex === 'function') {
    for (var _try = 0; _try < 8; _try++) {
      var _candidate = pickSolarCycleProvinceHex(seedSolarCycleMix(state, day + stories.length * 37 + _try * 11));
      if (!_candidate) continue;
      var _candidateKey = String(_candidate.col) + ',' + String(_candidate.row);
      if (!S.missionTokens[_candidateKey]) {
        _sideHex = _candidate;
        _sideKey = _candidateKey;
        break;
      }
    }
  }
  if (_sideHex && _sideKey) {
    S.missionTokens[_sideKey] = {
      missionId: 'solar_cycle_story',
      type: 'solar_cycle_side',
      nsSubtype: 'sidestory',
      schedulerQuest: false,
      storyType: 'sidestory',
      sideStoryId: story.id,
      title: template.characterType + ': ' + template.name,
      text: template.intro,
      expiresDay: Number(state.daysElapsed || 0) + 8
    };
    story.mapKey = _sideKey;
    if (typeof renderHexMap === 'function') renderHexMap();
  }
  if (typeof showNotif === 'function') {
    var pacingLabel = Number(profile.bias || 0) >= 4
      ? 'Faction pressure rising'
      : (Number(profile.bias || 0) <= -4 ? 'Lore threads converging' : 'World pulse update');
    showNotif('Side quest appeared: ' + String(template.characterType) + ' — ' + String(template.name) + '. ' + pacingLabel + '.', 'info');
  }
  return story;
}

function openSolarCycleSideStoryModal(storyId) {
  var state = ensureSolarCycleState();
  var story = getSolarCycleSideStoryById(storyId, state);
  if (!story || !story.active || story.completed || story.failed || typeof openModal !== 'function') return false;

  var template = null;
  for (var i = 0; i < SOLAR_CYCLE_SIDE_STORY_TEMPLATES.length; i++) {
    if (SOLAR_CYCLE_SIDE_STORY_TEMPLATES[i].id === story.templateId) { template = SOLAR_CYCLE_SIDE_STORY_TEMPLATES[i]; break; }
  }
  if (!template) return false;
  var beat = template.beats[story.beatIndex];
  if (!beat) return false;

  var beatLabel = 'Beat ' + (story.beatIndex + 1) + ' / ' + template.beats.length;
  var actionButtons = SOLAR_CYCLE_ACTION_STATS.map(function (stat) {
    var action = beat.actions[stat];
    if (!action) return '';
    var colorClass = action.tone === 'positive' ? 'btn-teal' : (action.tone === 'aggressive' ? 'btn-red' : '');
    return '<button class="btn btn-sm ' + colorClass + '" style="margin:.15rem;" onclick="window.advanceSolarCycleSideStoryBeat(\'' + escapeSolarCycleHtml(storyId) + '\',\'' + stat + '\');">'
      + escapeSolarCycleHtml(String(stat).toUpperCase()) + ': ' + escapeSolarCycleHtml(action.label) + '</button>';
  }).join('');

  openModal(
    'Side Story — ' + escapeSolarCycleHtml(story.characterType) + ': ' + escapeSolarCycleHtml(story.characterName),
    '<div style="font-size:.72rem;color:var(--muted2);margin-bottom:.25rem;">' + escapeSolarCycleHtml(beatLabel) + ' | Day ' + Number(story.spawnDay || 0) + '</div>'
    + '<div style="font-size:.76rem;color:var(--gold2);line-height:1.55;margin-bottom:.35rem;font-style:italic;">' + escapeSolarCycleHtml(story.intro) + '</div>'
    + '<div style="font-size:.78rem;color:var(--text2);line-height:1.6;margin-bottom:.4rem;">' + escapeSolarCycleHtml(beat.prompt) + '</div>'
    + '<div style="display:flex;flex-wrap:wrap;gap:.1rem;margin-bottom:.4rem;">' + actionButtons + '</div>'
    + '<div style="font-size:.71rem;color:var(--muted2);line-height:1.5;">Fate echo: ' + escapeSolarCycleHtml(story.fateHint) + '</div>'
  );
  return true;
}

function advanceSolarCycleSideStoryBeat(storyId, statKey) {
  var state = ensureSolarCycleState();
  var story = getSolarCycleSideStoryById(storyId, state);
  if (!story || !story.active || story.completed || story.failed) return;

  var template = null;
  for (var i = 0; i < SOLAR_CYCLE_SIDE_STORY_TEMPLATES.length; i++) {
    if (SOLAR_CYCLE_SIDE_STORY_TEMPLATES[i].id === story.templateId) { template = SOLAR_CYCLE_SIDE_STORY_TEMPLATES[i]; break; }
  }
  if (!template) return;
  var beat = template.beats[story.beatIndex];
  if (!beat) return;

  var action = beat.actions[String(statKey)];
  if (!action) return;

  var clearSideStoryMapToken = function () {
    if (!story.mapKey || typeof S === 'undefined' || !S || !S.missionTokens) return;
    var token = S.missionTokens[String(story.mapKey)];
    if (token && token.missionId === 'solar_cycle_story' && String(token.storyType || '') === 'sidestory') {
      delete S.missionTokens[String(story.mapKey)];
      if (typeof renderHexMap === 'function') renderHexMap();
    }
  };

  // Apply consequence deltas
  var cons = action.consequence || {};
  if (typeof recordWorldConsequence === 'function') {
    var deltaEntries = Object.keys(cons);
    deltaEntries.forEach(function (k) {
      if (cons[k] && cons[k] !== 0) {
        recordWorldConsequence('side_story_' + story.templateId + '_' + beat.id + '_' + statKey, k, Number(cons[k]), 'side_story');
      }
    });
  }
  if (typeof applySolarCycleWorldFabricDelta === 'function') {
    applySolarCycleWorldFabricDelta(state, cons);
  }

  var resultText = String(action.result || '');
  var outcome = String(action.outcome || 'advance');

  // Prophecy trace for complete outcomes
  if (outcome === 'complete' && state.prophecyTrack) {
    state.prophecyTrack.push('Side story [' + template.name + '] concluded: ' + String(statKey).toUpperCase() + ' — ' + String(action.label || ''));
  }

  var notifMsg = '';
  if (outcome === 'fail') {
    story.active = false;
    story.failed = true;
    clearSideStoryMapToken();
    notifMsg = resultText + ' [Branch closed]';
  } else if (outcome === 'complete') {
    story.active = false;
    story.completed = true;
    notifMsg = resultText + ' [Story complete]';
      // Award the lore codex reward
      if (template.loreReward && typeof addToBackpack === 'function') {
        var _rewarded = addToBackpack(template.loreReward);
        if (_rewarded && typeof showNotif === 'function') {
          showNotif('Side quest reward: ' + template.loreReward + ' added to backpack.', 'good');
        }
      }
      // Clear the map marker
      if (story.mapKey && typeof S !== 'undefined' && S && S.missionTokens) {
        delete S.missionTokens[story.mapKey];
        if (typeof renderHexMap === 'function') renderHexMap();
      }
  } else if (outcome === 'combat') {
    story.active = false;
    story.failed = true;
    clearSideStoryMapToken();
    notifMsg = resultText + ' [Combat triggered]';
    if (typeof showNotif === 'function') showNotif('Side Story: ' + resultText, 'warn');
    if (typeof startProvinceMonsterCombat === 'function') {
      startProvinceMonsterCombat(String(story.characterType), 8, 1);
    }
    return;
  } else {
    story.beatIndex = Math.min(story.beatIndex + 1, template.beats.length - 1);
    notifMsg = resultText;
    // Relocate the side-story marker to a new hex so the character feels like they moved.
    if (story.mapKey && typeof S !== 'undefined' && S && S.missionTokens) {
      var _oldKey = String(story.mapKey);
      var _newSideHex = null;
      var _newSideKey = '';
      if (typeof pickSolarCycleProvinceHex === 'function') {
        for (var _rt = 0; _rt < 8; _rt++) {
          var _rcandidate = pickSolarCycleProvinceHex(seedSolarCycleMix(state, Number(state.daysElapsed || 0) + story.beatIndex * 53 + _rt * 17));
          if (!_rcandidate) continue;
          var _rcandidateKey = String(_rcandidate.col) + ',' + String(_rcandidate.row);
          if (_rcandidateKey !== _oldKey && !S.missionTokens[_rcandidateKey]) {
            _newSideHex = _rcandidate;
            _newSideKey = _rcandidateKey;
            break;
          }
        }
      }
      if (_newSideHex && _newSideKey) {
        var _existingToken = S.missionTokens[_oldKey];
        delete S.missionTokens[_oldKey];
        S.missionTokens[_newSideKey] = Object.assign({}, _existingToken || {}, {
          missionId: 'solar_cycle_story',
          type: 'solar_cycle_side',
          nsSubtype: 'sidestory',
          storyType: 'sidestory',
          sideStoryId: story.id,
          expiresDay: Number(state.daysElapsed || 0) + 8
        });
        story.mapKey = _newSideKey;
        if (typeof renderHexMap === 'function') renderHexMap();
      }
    }
  }

  if (typeof closeModal === 'function') closeModal();
  if (typeof showNotif === 'function') showNotif('Side Story: ' + notifMsg, outcome === 'fail' ? 'error' : 'success');
}

window.openSolarCycleSideStoryModal = openSolarCycleSideStoryModal;
window.advanceSolarCycleSideStoryBeat = advanceSolarCycleSideStoryBeat;
window.maybeSpawnSolarCycleSideStory = maybeSpawnSolarCycleSideStory;
window.getSolarCycleItemDescription = getSolarCycleItemDescription;
